<script setup lang="ts">import type {Cell} from '../types/domain';import {number} from '../utils/format';defineProps<{cells:Cell[];a:string[];b:string[]}>();</script><template><section class="cell-matrix"><div class="section-heading"><h2>处理格实验记录</h2><span>温度 × 釉层 / MPa</span></div><div class="table-wrap"><table><thead><tr><th>釉层</th><th v-for="level in a" :key="level">{{level}}°C</th></tr></thead><tbody><tr v-for="glaze in b" :key="glaze"><th>{{glaze}}</th><td v-for="temp in a" :key="temp"><b>{{number(cells.find(c=>c.temperature===temp&&c.glaze===glaze)?.mean,2)}}</b><small>n={{cells.find(c=>c.temperature===temp&&c.glaze===glaze)?.n||0}} / 独立试片</small></td></tr></tbody></table></div></section></template>
